///        |               |          |      |
///        |               |          +------+
///        +-------+-------+
///                v
///        [complete output record]
/// ```
/// # Examples
/// Private adapter context; this builds values only and does not send a message.
/// ```text
/// let input = lsp_types::SignatureInformationSettings {
///     documentation_format: None,
///     parameter_information: None,
///     active_parameter_support: None,
/// };
/// let output = decode_signature_information_settings(input)?;
/// ```
pub(in crate::server::wrapper) fn decode_signature_information_settings(
    v: lsp_types::SignatureInformationSettings,
) -> Result<d::SignatureInformationSettings, ServerError> {
    Ok::<_, ServerError>(d::SignatureInformationSettings {
        documentation_format: (v.documentation_format)
            .map(|v| {
                Ok::<_, ServerError>(
                    (v).into_iter()
                        .map(decode_markup_kind)
                        .collect::<Result<Vec<_>, ServerError>>()?,
                )
            })
            .transpose()?,
        parameter_information: (v.parameter_information)
            .map(decode_parameter_information_settings)
            .transpose()?,
        active_parameter_support: v.active_parameter_support,
    })
}
